import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百四十九章 什么才是清净的说法","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/149第一百四十九章 什么才是清净的说法.md","filePath":"meditation/巴利文大藏经/149第一百四十九章 什么才是清净的说法.md"}'),o={name:"meditation/巴利文大藏经/149第一百四十九章 什么才是清净的说法.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百四十九章-什么才是清净的说法" tabindex="-1">第一百四十九章 什么才是清净的说法 <a class="header-anchor" href="#第一百四十九章-什么才是清净的说法" aria-label="Permalink to &quot;第一百四十九章 什么才是清净的说法&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应3经/如月亮经(迦叶相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，你们到世间人的家中去的时候，要像月亮那样的皎洁清净，要像刚出家那个时候一样的谦虚有礼，一定不要生起傲慢之心。</p><p>弟子们，就如同一个男子他看着深不见底的水井，站在高耸如云的悬崖旁边，在浩瀚的海洋深处划船一样，他会调整好自己的身心，不会有丝毫的懈怠和粗心，因为他一旦懈怠，一旦粗心大意就可能会失去生命。弟子们，同样的道理，你们到世间人的家中去的时候也要保持一颗谦虚谨慎的心，要调整好自己的身心，不要骄傲自大。</p><p>弟子们，你们现在是如何想的？什么样的出家人才有资格到世间人的家中去呢？”</p><p>出家弟子们回答：“世尊您是我们的皈依，您是我们的导师，我们按您所说的法去修行，如果世尊您能够为我们讲解：「什么样的出家人才有资格到世间人的家中去？」我们会在听您说法后，按您所说的去做的，去修行的，我们会时刻都受持世尊您对我们所说的正法的。”</p><p>这时，佛陀在空中挥动着自己的一只手，对出家弟子们说：“弟子们，就如同如来这只在空中挥动的手一样，如来的这只手因为是在虚空中挥动，所以就不会被束缚捆绑，就不会被阻碍、阻拦，就不会被任何事物粘住、黏住，就不会被任何人或事物捉住、抓住。同样的道理，弟子们，如果有一位出家人，他到世间人的家里去的时候，他的内心也不被任何的事物束缚捆绑，阻碍阻拦，粘住黏住，捉住抓住，他的内心不胡思乱想、不散乱，他的内心能够保持清净。并且他对于世间人的各种供养不会生起贪求的念想，当世间人供养他的时候，他也会接受供养，以此来为世间供养他的人种植福德。当这些供养他的世间人获得福德的时候，他不会由此开心欢喜；当这些世间人不供养他的时候，他也不会由此悲伤痛苦。他不会产生喜怒哀乐等等任何的念想，弟子们，这位出家人不会因为任何事物或人的影响而改变清净的境界，他就是有资格到世间人家里面去的出家人。</p><p>弟子们，迦叶尊者就是这样的修行人，他到世间人家里去的时候，他的内心不会被任何的事物束缚捆绑，阻碍阻拦，粘住黏住，捉住抓住，他的内心不会胡思乱想，不会散乱，他的内心能够保持清净。并且他对于世间人的各种供养不会生起贪求的念想，当世间人供养他的时候，他也会接受供养，以此来为世间供养他的人种植福德。当这些供养他的世间人获得福德的时候，他不会由此开心欢喜；当这些世间人不供养他的时候，他也不会由此悲伤痛苦。他不会产生喜怒哀乐等等任何的念想，弟子们，迦叶尊者不会因为任何事物或人的影响而改变清净的境界，他就是有资格到世间人家里面去的出家人。</p><p>弟子们，你们现在是怎么想的？对世间人如何的说法是不清净的说法？对世间人如何的说法是清净的说法？”</p><p>出家弟子们回答：“世尊您是我们的皈依，您是我们的导师，我们按您所说的法去修行，如果世尊您能够为我们讲解：「什么样的说法是不清净的说法？什么样的说法才是清净的说法？」我们会在听您说法后，按您所说的去做的，去修行的，我们会时刻都受持世尊您对我们所说的正法的。”</p><p>佛陀说：“弟子们，那你们就要认真的听如来说法了，那你们就要仔细的思考了。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细思考的。”</p><p>佛陀说：“弟子们，任何的出家人，他们对世间人说法的时候，内心是这样想的：「啊，希望他们从我这里听到法，希望他们在听我说法后，能够生起欢喜心，能够对我说的法生起坚固的信心，由此让他们对我也生起欢喜心，对我也生起坚固的信心。他们听我说法后，会更加尊敬我，会拿出更多的物品来供养我。」弟子们，如果说法的出家人是这样想的，不管他们对世间人说的法有多么的好，都是不清净的说法。</p><p>弟子们，任何的出家人，他们对世间人说法的时候，内心这样的想：「这个法是如来所说的，我只是代如来来为世间人讲解，我一定要讲的浅显易懂，我一定要用最简单易懂的言语来为世间人讲解如来的正法，让听法的世间人能够立刻、直接、即时的明白如来所说正法的义理。这些已经听法的世间人能够由此按照如来的正法去修行，他们能够因此开启智慧，并身体力行的去实践修行。我也是沿着如来的正法去修行才有了现在的清净境界，我会告诉世间人：不要迷信和迷恋任何口中说出来的各种清净境界，要以自己实践的修行体悟来验证如来所说正法中的各种清净境界，要用自己的实践来验证而不是毫无理由的坚信任何口中说出的各种清净境界。祈愿他们听闻我代如来说法后，能够生起对如来正法的坚固信心，能够持之以恒的去实践修行，能够由此除灭一切的烦恼和痛苦，能够由此从生死轮回中解脱出来，能够由此最终达到不生不灭涅槃的境界。」弟子们，像这样，完全是出于对世间人的慈悲，完全是为了让如来的正法能够简单明了、浅显易懂的被世间人理解和接受，完全是想让听法的世间人从烦恼和痛苦中解脱出来，完全是为了让世间人从生死轮回中永远的解脱出来，完全是为了让世间人能够达到不生不灭涅槃的境界，除此之外，没有其他的贪求心，没有其他为自己获得利益的念想，弟子们，这样的说法就是清净的说法。</p><p>弟子们，迦叶尊者也是这样为世间人讲解如来的正法的，迦叶尊者对世间人说法的时候会这样的想：「这个法是如来所说的，我只是代如来来为世间人讲解，我一定要讲的浅显易懂，一定要用最简单易懂的言语来为世间人讲解如来的正法，让听法的世间人能够立刻、直接、即时的明白如来所说正法的义理。这些已经听法的世间人能够由此按照如来的正法去修行，他们能够因此开启智慧，并身体力行的去实践修行。我也是沿着如来的正法去修行才有了现在的清净境界，我会告诉世间人：不要迷信和迷恋任何口中说出来的各种清净境界，要以自己实践的修行体悟来验证如来所说正法中的各种清净境界，要用自己的实践来验证而不是毫无理由的坚信任何口中说出的各种清净境界。祈愿他们听闻我代如来说法后，能够生起对如来正法的坚固信心，能够持之以恒的去实践修行，能够由此除灭一切的烦恼和痛苦，能够由此从生死轮回中解脱出来，能够由此最终达到不生不灭涅槃的境界。」弟子们，像这样，迦叶尊者完全是出于对世间人的慈悲，完全是为了让如来的正法能够简单明了、浅显易懂的被世间人理解和接受，完全是想让听法的世间人从烦恼和痛苦中解脱出来，完全是为了让世间人从生死轮回中永远的解脱出来，完全是为了让世间人能够达到不生不灭涅槃的境界，除此之外，迦叶尊者没有其他的贪求心，没有其他为自己获得利益的念想。</p><p>弟子们，你们应该以迦叶尊者为榜样，应该以这样清净说法的出家人们为榜样，如来其实是在用迦叶尊者和清净说法出家人们的修行实践在教导你们，你们应该按这样的方法去实践的修行。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',18)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
